S = "Hakeem Force Academy"
QS = [
(S, "What was the name of the 1917 revolution in Russia (USSR) that overthrew the Tsarist system?", ["French Revolution", "Bolshevik (October) Revolution", "Glorious Revolution", "Industrial Revolution"], 1,
 "In 1917 the Bolsheviks led by Lenin seized power in Russia, ending Tsarist and provisional rule. It is known as the Bolshevik or October Revolution.",
 "The USSR itself was formed in 1922 and dissolved in 1991.", 1),
(S, "How many Muslims took part in the Battle of Badr?", ["313", "700", "1000", "3000"], 0,
 "The Muslim army at Badr numbered about 313 men, against roughly 1000 Quraish soldiers.",
 "Badr was fought on 17 Ramadan 2 AH (624 CE).", 3),
(S, "Which international organization was the predecessor of the United Nations (UNO)?", ["NATO", "League of Nations", "Commonwealth", "Warsaw Pact"], 1,
 "The League of Nations, founded in 1920 after World War I, failed to prevent World War II and was replaced by the UN in 1945.",
 "The League of Nations was headquartered in Geneva.", 1),
(S, "What was the main purpose of Operation Radd-ul-Fasaad launched by Pakistan in 2017?", ["To eliminate residual and latent terrorism and consolidate earlier gains", "To capture Siachen", "To fight a war with India", "To evacuate flood victims"], 0,
 "Operation Radd-ul-Fasaad was a nationwide intelligence-based counter-terrorism operation launched in February 2017. It aimed to eliminate remaining terrorist threats after Operation Zarb-e-Azb.",
 "Operation Zarb-e-Azb began in North Waziristan in June 2014.", 1),
(S, "What was the relation of Hazrat Umme Kalsoom (Umm Kulthum) to the Holy Prophet (PBUH)?", ["Wife", "Daughter", "Mother", "Paternal aunt"], 1,
 "Hazrat Umm Kulthum (RA) was a daughter of the Prophet (PBUH) and Hazrat Khadija (RA). She was married to Hazrat Uthman (RA) after the death of her sister Ruqayyah.",
 "Hazrat Uthman (RA) is called Dhun-Nurayn for marrying two daughters of the Prophet.", 1),
(S, "What was the relation of Hazrat Hafsa (RA) with the Holy Prophet (PBUH)?", ["Daughter", "Foster mother", "Wife", "Paternal aunt"], 2,
 "Hazrat Hafsa (RA), daughter of Hazrat Umar (RA), married the Prophet (PBUH) and is a Mother of the Believers.",
 "The first compiled copy of the Quran was kept with Hazrat Hafsa (RA).", 1),
(S, "What was the relation of Hazrat Ayesha (RA) with the Holy Prophet (PBUH)?", ["Daughter", "Wife", "Cousin", "Mother"], 1,
 "Hazrat Ayesha (RA), daughter of Hazrat Abu Bakr (RA), was a wife of the Prophet (PBUH) and a Mother of the Believers.",
 "She is a major narrator of hadith.", 1),
(S, "In which period did Hazrat Umar (RA) hold the caliphate?", ["632 to 634 CE", "634 to 644 CE", "644 to 656 CE", "656 to 661 CE"], 1,
 "Hazrat Umar (RA) became caliph after Hazrat Abu Bakr (RA) in 634 CE and was martyred in 644 CE, ruling about ten and a half years.",
 "His caliphate corresponds to roughly 13 to 23 AH.", 1),
(S, "What title is associated with Liaquat Ali Khan?", ["Quaid-e-Azam", "Quaid-e-Millat", "Allama", "Sir Syed"], 1,
 "Liaquat Ali Khan, the first Prime Minister of Pakistan, is known as Quaid-e-Millat (Leader of the Nation).",
 "He was assassinated in Rawalpindi on 16 October 1951 and is also called Shaheed-e-Millat.", 1),
(S, "What was the Simla Conference of 1945?", ["A meeting of Wavell with Indian leaders on self-government that failed", "The signing of the Pakistan-India peace agreement", "The announcement of the Partition Plan", "The first session of the Constituent Assembly"], 0,
 "The Viceroy Lord Wavell called Indian leaders to Simla in June-July 1945 to discuss an Executive Council. It failed because Congress and the Muslim League could not agree on who nominates Muslim members.",
 "The Wavell Plan was rejected as the Muslim League insisted on being the sole representative of Muslims.", 1),
(S, "What was the so-called Pig War between the United States and Britain over?", ["Control of San Juan Island", "Control of Gibraltar", "Trade in pork", "The Suez Canal"], 0,
 "The Pig War of 1859 was a border dispute over San Juan Island; it began after an American farmer shot a British-owned pig. The only casualty was the pig.",
 "The dispute was settled by arbitration in 1872 in favour of the United States.", 1),
(S, "According to the Hadith, what will a person be asked about first on the Day of Judgement regarding the rights of Allah?", ["Zakat", "Salah (prayer)", "Hajj", "Fasting"], 1,
 "The Prophet (PBUH) said that the first thing a servant will be called to account for on the Day of Judgement is prayer (Salah).",
 "Regarding rights between people, the first matter judged will be bloodshed.", 1),
(S, "When an ant stings, which acid is injected into the body?", ["Formic acid", "Citric acid", "Lactic acid", "Acetic acid"], 0,
 "Ant venom contains formic acid, which causes the burning pain of the sting.",
 "Formic acid gets its name from the Latin word formica meaning ant.", 1),
(S, "When did the COVID-19 (coronavirus) pandemic begin?", ["2015", "2017", "2019", "2021"], 2,
 "The first cases were reported in Wuhan, China, in December 2019.",
 "The WHO declared COVID-19 a pandemic on 11 March 2020.", 1),
(S, "In which year did East Pakistan separate from Pakistan to become Bangladesh?", ["1965", "1970", "1971", "1973"], 2,
 "East Pakistan broke away after the 1971 war, and the Dhaka surrender took place on 16 December 1971.",
 "The Hamoodur Rehman Commission investigated the causes of the 1971 debacle.", 1),
(S, "In which year of the Hijri calendar did the Holy Prophet (PBUH) perform Umrat-ul-Qaza?", ["6 AH", "7 AH", "8 AH", "9 AH"], 1,
 "After the Treaty of Hudaibiya the Muslims performed the Umrah they were stopped from in 6 AH. They did it the next year, in 7 AH.",
 "It is called Umrat-ul-Qaza because it made up for the Umrah missed in 6 AH.", 1),
(S, "In which year of prophethood did Hazrat Umar (RA) embrace Islam, according to most Pakistani textbooks?", ["1st year", "3rd year", "6th year", "10th year"], 2,
 "Hazrat Umar (RA) accepted Islam in the 6th year of prophethood, after the Prophet's prayer that Allah strengthen Islam through one of the two Umars.",
 "Sources differ slightly, some placing it in the 5th year.", 1),
(S, "On which occasion did Hinda (wife of Abu Sufyan) accept Islam?", ["Battle of Badr", "Battle of Uhud", "Conquest of Makkah", "Battle of Khandaq"], 2,
 "Hinda bint Utbah, who had opposed Islam at Uhud, accepted Islam when Makkah was conquered in 8 AH.",
 "Her son Hazrat Muawiya (RA) later founded the Umayyad dynasty.", 2),
(S, "When did India first present the Kashmir issue to the United Nations?", ["1 January 1948", "14 August 1947", "5 February 1949", "1 January 1950"], 0,
 "India took the Kashmir dispute to the UN Security Council on 1 January 1948 under Article 35 of the UN Charter.",
 "The UNCIP resolutions of 1948-49 called for a plebiscite in Kashmir.", 1),
(S, "What was the legislature setup under the 1956 Constitution of Pakistan?", ["Bicameral with a Senate", "Unicameral National Assembly", "Three houses", "Provincial assemblies only"], 1,
 "The 1956 Constitution created a single-house (unicameral) National Assembly with equal representation (parity) for East and West Pakistan.",
 "The 1956 Constitution was abrogated by Ayub Khan's martial law in October 1958.", 1),
]
